/// Record exponential: z = exp(a)
#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_tape_exp(tape: *mut c_void, a: u32) -> u32 {
    if tape.is_null() {
        return u32::MAX;
    }
    unsafe {
        let tape = &mut *(tape as *mut NativeTape);
        tape.record_unary(NativeTapeOp::Exp, a)
    }
}

