/// Get the forward value at a tape index.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_tape_value(tape: *const c_void, idx: u32) -> f64 {
    if tape.is_null() {
        return f64::NAN;
    }
    unsafe {
        let tape = &*(tape as *const NativeTape);
        tape.value(idx)
    }
}

/// Reverse-mode autodiff: tape-based backpropagation.
///
/// Runs the backward sweep on a previously-built tape, seeding the gradient
/// of the last recorded value with `output_gradient`, then writes the
/// gradients w.r.t. each input into `input_gradients[0..n_inputs]`.
///
/// C signature: void sounio_autodiff_reverse(
///     void* tape,                   // Computation tape
///     double output_gradient,       // Gradient w.r.t. output
///     double* input_gradients,      // Output: gradients w.r.t. inputs
///     int n_inputs                  // Number of inputs
/// )
#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_autodiff_reverse(
    tape: *mut c_void,
    output_gradient: f64,
    input_gradients: *mut f64,
    n_inputs: i32,
) {
    if tape.is_null() || input_gradients.is_null() || n_inputs <= 0 {
        return;
    }

    unsafe {
        let tape = &mut *(tape as *mut NativeTape);

        // The output is the last allocated value
        let output_idx = if tape.next_idx > 0 {
            tape.next_idx - 1
        } else {
            return;
        };

        let grads = tape.backward(output_idx, output_gradient);

        // Copy gradients to output buffer
        let n = (n_inputs as usize).min(grads.len());
        for i in 0..n {
            *input_gradients.add(i) = grads[i];
        }
    }
}

/// Forward-mode autodiff: dual number exponential
/// C signature: void sounio_dual_exp(Dual* x, Dual* result)
#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_dual_exp(x: *const Dual, result: *mut Dual) {
    if x.is_null() || result.is_null() {
        return;
    }

    unsafe {
        let x_val = (*x).value;
        let x_der = (*x).derivative;

        let exp_val = x_val.exp();
        // d/dx(exp(x)) = exp(x) * x'
        (*result).value = exp_val;
        (*result).derivative = exp_val * x_der;
    }
}

/// Forward-mode autodiff: dual number logarithm
/// C signature: void sounio_dual_log(Dual* x, Dual* result)
#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_dual_log(x: *const Dual, result: *mut Dual) {
    if x.is_null() || result.is_null() {
        return;
    }

    unsafe {
        let x_val = (*x).value;
        let x_der = (*x).derivative;

        if x_val <= 0.0 {
            (*result).value = f64::NAN;
            (*result).derivative = f64::NAN;
            return;
        }

        // d/dx(ln(x)) = x' / x
        (*result).value = x_val.ln();
        (*result).derivative = x_der / x_val;
    }
}

/// Forward-mode autodiff: dual number sine
/// C signature: void sounio_dual_sin(Dual* x, Dual* result)
#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_dual_sin(x: *const Dual, result: *mut Dual) {
    if x.is_null() || result.is_null() {
        return;
    }

    unsafe {
        let x_val = (*x).value;
        let x_der = (*x).derivative;

        // d/dx(sin(x)) = cos(x) * x'
        (*result).value = x_val.sin();
        (*result).derivative = x_val.cos() * x_der;
    }
}

/// Forward-mode autodiff: dual number cosine
/// C signature: void sounio_dual_cos(Dual* x, Dual* result)
#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_dual_cos(x: *const Dual, result: *mut Dual) {
    if x.is_null() || result.is_null() {
        return;
    }

    unsafe {
        let x_val = (*x).value;
        let x_der = (*x).derivative;

        // d/dx(cos(x)) = -sin(x) * x'
        (*result).value = x_val.cos();
        (*result).derivative = -x_val.sin() * x_der;
    }
}

/// Forward-mode autodiff: dual number power (x^p where p is constant)
/// C signature: void sounio_dual_pow(Dual* x, double power, Dual* result)
#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_dual_pow(x: *const Dual, power: f64, result: *mut Dual) {
    if x.is_null() || result.is_null() {
        return;
    }

    unsafe {
        let x_val = (*x).value;
        let x_der = (*x).derivative;

        if x_val <= 0.0 && power != power.floor() {
            // Negative base with non-integer exponent
            (*result).value = f64::NAN;
            (*result).derivative = f64::NAN;
            return;
        }

        let pow_val = x_val.powf(power);
        // d/dx(x^p) = p * x^(p-1) * x'
        (*result).value = pow_val;
        (*result).derivative = power * x_val.powf(power - 1.0) * x_der;
    }
}

/// Forward-mode autodiff: dual number square root
/// C signature: void sounio_dual_sqrt(Dual* x, Dual* result)
#[unsafe(no_mangle)]
pub unsafe extern "C" fn sounio_dual_sqrt(x: *const Dual, result: *mut Dual) {
    if x.is_null() || result.is_null() {
        return;
    }

    unsafe {
        let x_val = (*x).value;
        let x_der = (*x).derivative;

        if x_val < 0.0 {
            (*result).value = f64::NAN;
            (*result).derivative = f64::NAN;
            return;
        }

        let sqrt_val = x_val.sqrt();
        // d/dx(sqrt(x)) = x' / (2 * sqrt(x))
        (*result).value = sqrt_val;
        (*result).derivative = x_der / (2.0 * sqrt_val);
    }
}

// =============================================================================
// Tests for reverse-mode tape
// =============================================================================

#[cfg(test)]
mod tests {
    use super::*;

    const EPS: f64 = 1e-10;

    fn approx_eq(a: f64, b: f64, tol: f64) -> bool {
        (a - b).abs() < tol
    }

    // --- Tape Rust API tests ---

    #[test]
    fn test_tape_add() {
        // f(x, y) = x + y → df/dx = 1, df/dy = 1
        let mut tape = NativeTape::new(2);
        let x = tape.record_input(0, 3.0);
        let y = tape.record_input(1, 5.0);
        let z = tape.record_binary(NativeTapeOp::Add, x, y);

        assert!(approx_eq(tape.value(z), 8.0, EPS));

        let grads = tape.backward(z, 1.0);
        assert!(approx_eq(grads[0], 1.0, EPS)); // df/dx
        assert!(approx_eq(grads[1], 1.0, EPS)); // df/dy
    }

    #[test]
    fn test_tape_mul() {
        // f(x, y) = x * y → df/dx = y, df/dy = x
        let mut tape = NativeTape::new(2);
        let x = tape.record_input(0, 3.0);
        let y = tape.record_input(1, 5.0);
        let z = tape.record_binary(NativeTapeOp::Mul, x, y);

        assert!(approx_eq(tape.value(z), 15.0, EPS));

        let grads = tape.backward(z, 1.0);
        assert!(approx_eq(grads[0], 5.0, EPS)); // df/dx = y
        assert!(approx_eq(grads[1], 3.0, EPS)); // df/dy = x
    }

    #[test]
    fn test_tape_sub_div() {
        // f(x, y) = (x - y) / y → df/dx = 1/y, df/dy = -x/y²
        let mut tape = NativeTape::new(2);
        let x = tape.record_input(0, 6.0);
        let y = tape.record_input(1, 2.0);
        let diff = tape.record_binary(NativeTapeOp::Sub, x, y);
        let z = tape.record_binary(NativeTapeOp::Div, diff, y);

        assert!(approx_eq(tape.value(z), 2.0, EPS)); // (6-2)/2 = 2

        let grads = tape.backward(z, 1.0);
        // df/dx = 1/y = 0.5
        assert!(approx_eq(grads[0], 0.5, EPS));
        // df/dy = d/dy((x-y)/y) = d/dy(x/y - 1) = -x/y²
        // But via chain rule on the tape:
        //   z = diff / y → d(diff) += 1/y = 0.5, d(y) += -(diff)*1/y² = -4/4 = -1
        //   diff = x - y → d(x) += 0.5, d(y) += -0.5
        //   total d(y) = -1 + (-0.5) = -1.5
        assert!(approx_eq(grads[1], -1.5, EPS)); // -x/y² = -6/4 = -1.5
    }

    #[test]
    fn test_tape_exp() {
        // f(x) = exp(x) → df/dx = exp(x)
        let mut tape = NativeTape::new(1);
        let x = tape.record_input(0, 2.0);
        let z = tape.record_unary(NativeTapeOp::Exp, x);

        let expected = 2.0_f64.exp();
        assert!(approx_eq(tape.value(z), expected, EPS));

        let grads = tape.backward(z, 1.0);
        assert!(approx_eq(grads[0], expected, EPS));
    }

    #[test]
    fn test_tape_log() {
        // f(x) = ln(x) → df/dx = 1/x
        let mut tape = NativeTape::new(1);
        let x = tape.record_input(0, 2.0);
        let z = tape.record_unary(NativeTapeOp::Log, x);

        assert!(approx_eq(tape.value(z), 2.0_f64.ln(), EPS));

        let grads = tape.backward(z, 1.0);
        assert!(approx_eq(grads[0], 0.5, EPS)); // 1/2
    }

    #[test]
    fn test_tape_sin_cos() {
        // f(x) = sin(x) + cos(x) → df/dx = cos(x) - sin(x)
        let mut tape = NativeTape::new(1);
        let x = tape.record_input(0, 1.0);
        let s = tape.record_unary(NativeTapeOp::Sin, x);
        let c = tape.record_unary(NativeTapeOp::Cos, x);
        let z = tape.record_binary(NativeTapeOp::Add, s, c);

        let expected = 1.0_f64.sin() + 1.0_f64.cos();
        assert!(approx_eq(tape.value(z), expected, EPS));

        let grads = tape.backward(z, 1.0);
        let expected_grad = 1.0_f64.cos() - 1.0_f64.sin();
        assert!(approx_eq(grads[0], expected_grad, EPS));
    }

    #[test]
    fn test_tape_pow() {
        // f(x) = x³ → df/dx = 3x²
        let mut tape = NativeTape::new(1);
        let x = tape.record_input(0, 2.0);
        let z = tape.record_pow(x, 3.0);

        assert!(approx_eq(tape.value(z), 8.0, EPS));

        let grads = tape.backward(z, 1.0);
        assert!(approx_eq(grads[0], 12.0, EPS)); // 3 * 2² = 12
    }

    #[test]
    fn test_tape_sqrt() {
        // f(x) = sqrt(x) → df/dx = 1/(2*sqrt(x))
        let mut tape = NativeTape::new(1);
        let x = tape.record_input(0, 4.0);
        let z = tape.record_unary(NativeTapeOp::Sqrt, x);

        assert!(approx_eq(tape.value(z), 2.0, EPS));

        let grads = tape.backward(z, 1.0);
        assert!(approx_eq(grads[0], 0.25, EPS)); // 1/(2*2) = 0.25
    }

    #[test]
    fn test_tape_tanh() {
        // f(x) = tanh(x) → df/dx = 1 - tanh²(x)
        let mut tape = NativeTape::new(1);
        let x = tape.record_input(0, 0.5);
        let z = tape.record_unary(NativeTapeOp::Tanh, x);

        let t = 0.5_f64.tanh();
        assert!(approx_eq(tape.value(z), t, EPS));

        let grads = tape.backward(z, 1.0);
        assert!(approx_eq(grads[0], 1.0 - t * t, EPS));
    }

    #[test]
    fn test_tape_sigmoid() {
        // f(x) = σ(x) → df/dx = σ(x)(1-σ(x))
        let mut tape = NativeTape::new(1);
        let x = tape.record_input(0, 1.0);
        let z = tape.record_unary(NativeTapeOp::Sigmoid, x);

        let s = 1.0 / (1.0 + (-1.0_f64).exp());
        assert!(approx_eq(tape.value(z), s, EPS));

        let grads = tape.backward(z, 1.0);
        assert!(approx_eq(grads[0], s * (1.0 - s), EPS));
    }

    #[test]
    fn test_tape_relu() {
        // f(x) = relu(x), positive input
        let mut tape = NativeTape::new(1);
        let x = tape.record_input(0, 3.0);
        let z = tape.record_unary(NativeTapeOp::Relu, x);
        assert!(approx_eq(tape.value(z), 3.0, EPS));
        let grads = tape.backward(z, 1.0);
        assert!(approx_eq(grads[0], 1.0, EPS));

        // negative input
        let mut tape2 = NativeTape::new(1);
        let x2 = tape2.record_input(0, -2.0);
        let z2 = tape2.record_unary(NativeTapeOp::Relu, x2);
        assert!(approx_eq(tape2.value(z2), 0.0, EPS));
        let grads2 = tape2.backward(z2, 1.0);
        assert!(approx_eq(grads2[0], 0.0, EPS));
    }

    #[test]
    fn test_tape_fma() {
        // f(x, y, z) = x * y + z → df/dx = y, df/dy = x, df/dz = 1
        let mut tape = NativeTape::new(3);
        let x = tape.record_input(0, 2.0);
        let y = tape.record_input(1, 3.0);
        let z = tape.record_input(2, 4.0);
        let r = tape.record_fma(x, y, z);

        assert!(approx_eq(tape.value(r), 10.0, EPS)); // 2*3 + 4

        let grads = tape.backward(r, 1.0);
        assert!(approx_eq(grads[0], 3.0, EPS)); // df/dx = y
        assert!(approx_eq(grads[1], 2.0, EPS)); // df/dy = x
        assert!(approx_eq(grads[2], 1.0, EPS)); // df/dz = 1
    }

    #[test]
    fn test_tape_composite_quadratic() {
        // f(x) = x² + 2x + 1 → df/dx = 2x + 2
        // At x=3: f(3)=16, f'(3)=8
        let mut tape = NativeTape::new(1);
        let x = tape.record_input(0, 3.0);
        let two = tape.record_const(2.0);
        let one = tape.record_const(1.0);
        let x_sq = tape.record_binary(NativeTapeOp::Mul, x, x);
        let two_x = tape.record_binary(NativeTapeOp::Mul, two, x);
        let sum1 = tape.record_binary(NativeTapeOp::Add, x_sq, two_x);
        let z = tape.record_binary(NativeTapeOp::Add, sum1, one);

        assert!(approx_eq(tape.value(z), 16.0, EPS));

        let grads = tape.backward(z, 1.0);
        assert!(approx_eq(grads[0], 8.0, EPS)); // 2*3 + 2 = 8
    }

    #[test]
    fn test_tape_rosenbrock() {
        // Rosenbrock: f(x,y) = (1-x)² + 100*(y-x²)²
        // df/dx = -2(1-x) + 100 * 2*(y-x²)*(-2x)
        //       = -2(1-x) - 400*x*(y-x²)
        // df/dy = 200*(y-x²)
        // At (1,1): f=0, df/dx=0, df/dy=0
        // At (0,0): f=1, df/dx=-2, df/dy=0
        let mut tape = NativeTape::new(2);
        let x = tape.record_input(0, 0.0);
        let y = tape.record_input(1, 0.0);
        let one = tape.record_const(1.0);
        let hundred = tape.record_const(100.0);

        let one_minus_x = tape.record_binary(NativeTapeOp::Sub, one, x);
        let term1 = tape.record_binary(NativeTapeOp::Mul, one_minus_x, one_minus_x);

        let x_sq = tape.record_binary(NativeTapeOp::Mul, x, x);
        let y_minus_xsq = tape.record_binary(NativeTapeOp::Sub, y, x_sq);
        let t2_sq = tape.record_binary(NativeTapeOp::Mul, y_minus_xsq, y_minus_xsq);
        let term2 = tape.record_binary(NativeTapeOp::Mul, hundred, t2_sq);

        let z = tape.record_binary(NativeTapeOp::Add, term1, term2);

        assert!(approx_eq(tape.value(z), 1.0, EPS));

        let grads = tape.backward(z, 1.0);
        assert!(approx_eq(grads[0], -2.0, EPS));
        assert!(approx_eq(grads[1], 0.0, EPS));
    }

    #[test]
    fn test_tape_chain_rule_deep() {
        // f(x) = exp(sin(x²)) — chain rule across 3 levels
        // f'(x) = exp(sin(x²)) * cos(x²) * 2x
        let x_val = 0.5;
        let mut tape = NativeTape::new(1);
        let x = tape.record_input(0, x_val);
        let x_sq = tape.record_binary(NativeTapeOp::Mul, x, x);
        let sin_xsq = tape.record_unary(NativeTapeOp::Sin, x_sq);
        let z = tape.record_unary(NativeTapeOp::Exp, sin_xsq);

        let xsq = x_val * x_val;
        let expected_val = xsq.sin().exp();
        assert!(approx_eq(tape.value(z), expected_val, EPS));

        let grads = tape.backward(z, 1.0);
        let expected_grad = expected_val * xsq.cos() * 2.0 * x_val;
        assert!(approx_eq(grads[0], expected_grad, EPS));
    }

    // --- C API tests (mirrors integration test pattern) ---

    #[test]
    fn test_c_api_reverse_mode() {
        // f(x, y) = x * y + x → df/dx = y + 1, df/dy = x
        // At x=3, y=5: f=18, df/dx=6, df/dy=3
        unsafe {
            let tape = sounio_tape_create(2);
            let x = sounio_tape_input(tape, 0, 3.0);
            let y = sounio_tape_input(tape, 1, 5.0);
            let xy = sounio_tape_mul(tape, x, y);
            let _z = sounio_tape_add(tape, xy, x);

            assert!(approx_eq(sounio_tape_value(tape, _z), 18.0, EPS));

            let mut grads = [0.0f64; 2];
            sounio_autodiff_reverse(tape, 1.0, grads.as_mut_ptr(), 2);

            assert!(approx_eq(grads[0], 6.0, EPS)); // df/dx = y + 1 = 6
            assert!(approx_eq(grads[1], 3.0, EPS)); // df/dy = x = 3

            sounio_tape_destroy(tape);
        }
    }

    #[test]
    fn test_c_api_exp_log_round_trip() {
        // f(x) = log(exp(x)) = x → df/dx = 1
        unsafe {
            let tape = sounio_tape_create(1);
            let x = sounio_tape_input(tape, 0, 2.5);
            let e = sounio_tape_exp(tape, x);
            let _z = sounio_tape_log(tape, e);

            assert!(approx_eq(sounio_tape_value(tape, _z), 2.5, 1e-9));

            let mut grad = 0.0f64;
            sounio_autodiff_reverse(tape, 1.0, &mut grad, 1);
            assert!(approx_eq(grad, 1.0, 1e-9));

            sounio_tape_destroy(tape);
        }
    }

    #[test]
    fn test_tape_neg() {
        // f(x) = -x → df/dx = -1
        let mut tape = NativeTape::new(1);
        let x = tape.record_input(0, 7.0);
        let z = tape.record_unary(NativeTapeOp::Neg, x);
        assert!(approx_eq(tape.value(z), -7.0, EPS));
        let grads = tape.backward(z, 1.0);
        assert!(approx_eq(grads[0], -1.0, EPS));
    }

    #[test]
    fn test_tape_gradient_accumulation() {
        // f(x) = x + x + x = 3x → df/dx = 3
        let mut tape = NativeTape::new(1);
        let x = tape.record_input(0, 2.0);
        let s1 = tape.record_binary(NativeTapeOp::Add, x, x);
        let z = tape.record_binary(NativeTapeOp::Add, s1, x);

        assert!(approx_eq(tape.value(z), 6.0, EPS));

        let grads = tape.backward(z, 1.0);
        assert!(approx_eq(grads[0], 3.0, EPS));
    }
}
